sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var body = request.body.data;
    var errors = [];

    if (!body || !body.hostname) {
        errors.push('hostname is required');
    }
    if (!body || ['hardware_status', 'software_detected'].indexOf(body.event_type) === -1) {
        errors.push('event_type must be hardware_status or software_detected');
    }
    if (errors.length) {
        response.setStatus(400);
        response.setBody({ status: 'error', errors: errors });
        return;
    }

    var gr = new GlideRecord('x_1839598_automa_0_hardware_stage');
    gr.initialize();

    var fields = ['hostname', 'event_type', 'ci_class', 'serial_number',
                  'warranty_expiration', 'lease_expiration', 'detected_software_json',
                  'scan_timestamp', 'discovery_source', 'raw_model', 'raw_status'];

    fields.forEach(function (f) {
        var v = body[f];
        if (v !== undefined && v !== null && v !== '') {
            if (typeof v === 'object') {
                v = JSON.stringify(v);
            }
            gr.setValue(f, v);
        }
    });

    var id = gr.insert();
    if (!id) {
        response.setStatus(500);
        response.setBody({ status: 'error', message: 'Insert failed' });
        return;
    }

    response.setStatus(201);
    response.setBody({ status: 'accepted', sys_id: id, hostname: body.hostname });
})(request, response);
